	o.DocumentSha256 = string(fbs.DocumentSha256())
	o.MissionId = string(fbs.MissionId())
	if fbsVal := fbs.Spec(nil); fbsVal != nil {
		o.Spec = id.ObjectIdFromFbs(fbsVal)
	}
	if fbsVal := fbs.SpecCid(nil); fbsVal != nil {
		o.SpecCid = id.ContentIdFromFbs(fbsVal)
	}
